SELECT COALESCE(MIN(CASE WHEN Occupation = 'Doctor' THEN Name END), 'NULL'), COALESCE(MIN(CASE WHEN Occupation = 'Professor' THEN Name END), 'NULL'), COALESCE(MIN(CASE WHEN Occupation = 'Singer' THEN Name END), 'NULL'), COALESCE(MIN(CASE WHEN Occupation = 'Actor' THEN Name END), 'NULL') FROM (SELECT Name, Occupation, ROW_NUMBER() OVER(PARTITION BY Occupation ORDER BY Name) row_num FROM OCCUPATIONS) t GROUP BY row_num ORDER BY row_num;
